class SlidingDeny:
    """滑动窗口拒绝器：统计 (ts-window, ts] 内失败次数，超限则拒绝。"""

    def __init__(self, max_failures, window):
        self.max_failures = max_failures
        self.window = window

    def should_deny(self, failure_times, ts):
        recent = [t for t in failure_times if ts - t <= self.window]
        return len(recent) >= self.max_failures

