from target import SlidingDeny

def test_no_failures():
    assert SlidingDeny(3, 60).should_deny([], 100) is False

def test_under_threshold():
    assert SlidingDeny(3, 60).should_deny([90, 95], 100) is False

def test_boundary_evicted():
    assert SlidingDeny(1, 60).should_deny([40], 100) is False
